package com.bank.fraud;

import java.util.Arrays;
import java.util.logging.*;

public class SlidingWindowDemo {
    private static final Logger log = Logger.getLogger(SlidingWindowDemo.class.getName());
    static {
        Logger root = Logger.getLogger("");
        for (Handler h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler ch = new ConsoleHandler();
        ch.setFormatter(new BankLogFormatter());
        root.addHandler(ch);
        root.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        SpendWindowAnalyzer analyzer = new SpendWindowAnalyzer();

        int[] amounts = {5, 1, 3, 8, 2, 4, 1}; // in thousands
        long[] rolling = analyzer.rollingSum(amounts, 3);
        log.info(() -> "Fixed window (k=3) rolling sums: " + Arrays.toString(rolling));

        int longest = analyzer.longestWithinLimit(amounts, 10);
        log.info(() -> "Longest streak within limit 10: " + longest);
    }
}

