class SpendWindowAnalyzer {
    private static final Logger log = Logger.getLogger(SpendWindowAnalyzer.class.getName());

    // FIXED-size window: add entering, subtract leaving. O(n).
    long[] rollingSum(int[] a, int k) {
        if (a.length < k) return new long[0];
        long[] out = new long[a.length - k + 1];
        long sum = 0;
        for (int r = 0; r < a.length; r++) {
            sum += a[r];
            if (r >= k) sum -= a[r - k];  // drop the element leaving the window
            if (r >= k - 1) out[r - k + 1] = sum;
        }
        return out;
    }

    // VARIABLE-size window: expand right, shrink left when over limit. O(n).
    int longestWithinLimit(int[] a, long limit) {
        int left = 0, best = 0;
        long sum = 0;
        for (int right = 0; right < a.length; right++) {
            sum += a[right];               // expand right
            while (sum > limit) {          // shrink left until valid
                sum -= a[left];
                left++;
            }
            best = Math.max(best, right - left + 1);
        }
        return best;
    }
}

